"""Four original-frame RGB sources for the backup-lamp intersection delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer actual backup-lamp emission or statutory outcome from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-10.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 100),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-8.0, 2.5, 2.5), (-5.0, 0.0, 0.0), (1280, 720), 85),
    "driver_reference": ((-12.0, 0.0, 1.7), (0.0, 0.0, 0.0), (1280, 720), 65),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans():
    return [CameraPlan(name, *spec) for name, spec in CAMERAS.items()]


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class LampCameraCapture:
    def __init__(self, world, carla_module, subject, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans():
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Independent saved-source comparison of exact C111294 cases."""
from hashlib import sha256
import json
from pathlib import Path

from lamp_finalizer import analyze


PAIRS = {
    'optional_equipment': ('no_backup_lamp_installed', 'forward_backup_lamp_off'),
    'forward_illumination': ('forward_backup_lamp_off', 'forward_backup_lamp_on'),
}
FIXED = ('law_id', 'cell_id', 'actor', 'ego_blueprint_id',
         'other_blueprint_id', 'approach_m', 'exit_m', 'ego_speed_mps',
         'other_speed_mps', 'rate_hz', 'duration_s', 'frames', 'cameras')


def _read(root, name):
    path = Path(root)/name
    return json.loads(path.read_text())


def audit(comparison_id, first_attempt, second_attempt):
    if comparison_id not in PAIRS:
        raise ValueError('Unknown exact comparison')
    expected = PAIRS[comparison_id]
    first, second = [Path(p) for p in (first_attempt, second_attempt)]
    configs = [_read(p, 'config.json') for p in (first, second)]
    if tuple(c['case_branch'] for c in configs) != expected:
        raise ValueError('Comparison exact-case identities differ')
    reports = [analyze(p, write_channels=False) for p in (first, second)]
    for key in FIXED:
        if configs[0].get(key) != configs[1].get(key):
            raise ValueError('Fixed construction condition differs: '+key)
    contexts = [_read(p, 'intersection_context.json') for p in (first, second)]
    if contexts[0] != contexts[1]:
        raise ValueError('Fixed intersection and other-vehicle context differs')
    equipment = [_read(p, 'equipment.json') for p in (first, second)]
    values = [r['measurements']['backup_lamp_forward']['value'] for r in reports]
    if comparison_id == 'optional_equipment':
        if (len(equipment[0]['installed_backup_lamps']),
                len(equipment[1]['installed_backup_lamps'])) != (0, 1):
            raise ValueError('Optional-equipment difference unobserved')
        if any(v['forward_with_native_lamp_bit_frames'] for v in values):
            raise ValueError('Lamp state changed in optional-equipment comparison')
    else:
        if len(equipment[0]['installed_backup_lamps']) != len(equipment[1]['installed_backup_lamps']):
            raise ValueError('Fixed installed backup-lamp inventory differs')
        if (values[0]['forward_with_native_lamp_bit_frames'] or
                not values[1]['forward_with_native_lamp_bit_frames']):
            raise ValueError('Forward lamp-state difference unobserved')
    # Require motion in both attempts without asserting exact physical equality.
    if not all(v['forward_frames'] for v in values):
        raise ValueError('Measured forward motion missing')
    return {'format': 'worker-comparison-audit', 'comparison_id': comparison_id,
            'case_ids': [r['case_id'] for r in reports],
            'source_hashes': [{name: sha256((p/name).read_bytes()).hexdigest()
                               for name in ('config.json', 'intersection_context.json',
                                            'equipment.json', 'motion.jsonl',
                                            'other_vehicle.jsonl', 'video_frames.jsonl')}
                              for p in (first, second)],
            'fixed_conditions_checked': True,
            'deliberate_difference_checked': True,
            'actual_pixels_reviewed': False,
            'physical_acceptance_claimed': False,
            'legal_acceptance_claimed': False}

"""Bind independent lamp-pixel review to retained original camera bytes.

The review records what a human saw; this checker only proves source identity,
frame coverage and that Native state is not substituted for visible emission.
"""

from hashlib import sha256
from pathlib import Path


CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def audit(observation, review, camera_paths, decode_receipt):
    if set(camera_paths) != set(CAMERAS):
        raise ValueError('All four original camera sources required')
    if not review.get('reviewer') or review.get('source_kind') != 'original_camera_pixels':
        raise ValueError('Independent original-pixel reviewer required')
    hashes = {}
    for name, path in camera_paths.items():
        path = Path(path)
        if not path.is_file() or not path.stat().st_size:
            raise ValueError('Missing original camera source: ' + name)
        hashes[name] = sha256(path.read_bytes()).hexdigest()
    if review.get('camera_sha256') != hashes:
        raise ValueError('Original camera source hash differs')
    if decode_receipt.get('camera_sha256') != hashes or decode_receipt.get('full_decode') is not True:
        raise ValueError('Full original camera decode receipt missing or stale')
    if review.get('lamp_view') not in CAMERAS or review.get('lamp_view_role') != 'rear_lamp_detail':
        raise ValueError('Rear lamp detail view not identified')
    original = observation.get('observations')
    if not isinstance(original, list) or not original:
        raise ValueError('Original motion observations missing')
    if review.get('decoded_frame_count') != len(original):
        raise ValueError('Original camera frame count differs')
    if decode_receipt.get('frame_counts') != {name: len(original) for name in CAMERAS}:
        raise ValueError('Full original camera frame counts differ')
    frames = observation.get('forward_frames')
    expected = [row['frame'] for row in original if row['forward_motion_observed']]
    if frames != expected:
        raise ValueError('Forward frame identity differs from original motion')
    decisions = review.get('forward_frame_reviews')
    if not isinstance(decisions, list) or [r.get('frame') for r in decisions] != frames:
        raise ValueError('Every original forward frame needs pixel review')
    states = []
    for row in decisions:
        state = row.get('visible_lamp_emission')
        if (state is not None and type(state) is not bool) or not row.get('pixel_observation'):
            raise ValueError('Original pixel observation incomplete')
        states.append(state)
    installed = observation.get('installed_backup_lamps')
    if not isinstance(installed, list):
        raise ValueError('Installed lamp inventory missing')
    if not installed and any(state is True for state in states):
        raise ValueError('Visible emission conflicts with absent lamp inventory')
    return {
        'format': 'worker-backup-lamp-pixel-audit',
        'camera_sha256': hashes,
        'forward_frames_reviewed': frames,
        'emission_observed_on_forward_frames': [f for f, state in zip(frames, states) if state is True],
        'emission_unknown_on_forward_frames': [f for f, state in zip(frames, states) if state is None],
        'pixel_review_complete': all(state is not None for state in states),
        'physical_acceptance_claimed': False,
        'legal_result': None,
    }

"""CARLA-lazy construction for the C111294 through-intersection comparison.

The simulator light bit is a control and readback, not proof of installed hardware
or emitted pixels. A separately sourced asset inventory is required at capture.
"""
from hashlib import sha256
import json
from math import atan2, cos, hypot, radians, sin
from pathlib import Path


def _xy(wp):
    p = wp.transform.location
    return (float(p.x), float(p.y))


def _yaw(wp):
    return float(wp.transform.rotation.yaw)


def _angle_difference(a, b):
    return abs((a - b + 180) % 360 - 180)


def _junction_id(wp):
    junction = wp.get_junction()
    return None if junction is None else int(junction.id)


def _unique_steps(wp, method, distance):
    options = getattr(wp, method)(distance)
    if len(options) != 1:
        raise ValueError('Ambiguous intersection through route')
    return options[0]


def discover_routes(world_map, *, approach_m=45., exit_m=35.):
    """Find a straight route and a perpendicular road through one junction.

    Map waypoints and actual junction IDs govern selection. Ambiguous candidates
    are rejected, allowing a local operator to pin a route instead of guessing.
    """
    candidates = {}
    for wp in world_map.generate_waypoints(2.0):
        jid = _junction_id(wp)
        if jid is None:
            continue
        try:
            start = _unique_steps(wp, 'previous', approach_m)
            end = _unique_steps(wp, 'next', exit_m)
        except ValueError:
            continue
        if _junction_id(start) is not None or _junction_id(end) is not None:
            continue
        if _angle_difference(_yaw(start), _yaw(end)) > 20:
            continue
        key = (jid, int(wp.road_id), int(wp.lane_id))
        candidates[key] = {'start': start, 'center': wp, 'end': end,
                           'junction_id': jid, 'road_id': int(wp.road_id),
                           'lane_id': int(wp.lane_id)}
    pairs = []
    routes = list(candidates.values())
    for i, ego in enumerate(routes):
        for other in routes[i+1:]:
            if ego['junction_id'] != other['junction_id'] or ego['road_id'] == other['road_id']:
                continue
            diff = _angle_difference(_yaw(ego['start']), _yaw(other['start']))
            if not 70 <= diff <= 110:
                continue
            pairs.append((ego, other))
    if len(pairs) != 1:
        raise ValueError('Need one unambiguous perpendicular intersection route pair')
    return pairs[0]


def validate_equipment_inventory(path, blueprint_id, expected_count):
    """Bind an independently authored asset inspection, never infer hardware from a bit."""
    path = Path(path)
    source = path.read_bytes()
    record = json.loads(source)
    lamps = record.get('installed_backup_lamps')
    if (record.get('blueprint_id') != blueprint_id or
            record.get('inspection_method') not in ('asset_mesh_review', 'physical_asset_review') or
            not record.get('inspector') or not isinstance(lamps, list) or
            len(lamps) != expected_count or
            any(not isinstance(x, dict) or not x.get('location') or
                not x.get('asset_source') for x in lamps)):
        raise ValueError('Sourced backup-lamp asset inventory missing or incompatible')
    return {'kind': 'motor_vehicle', 'blueprint_id': blueprint_id,
            'blueprint_source_sha256': sha256(source).hexdigest(),
            'installed_backup_lamps': lamps,
            'inspection_method': record['inspection_method'],
            'inspector': record['inspector']}


def construct(world, carla, config, equipment_inventory):
    """Create a separate ego and other vehicle with fixed scene purpose."""
    ego_route, other_route = discover_routes(world.get_map(),
        approach_m=config['approach_m'], exit_m=config['exit_m'])
    library = world.get_blueprint_library()
    ego_bp = library.find(config['ego_blueprint_id'])
    other_bp = library.find(config['other_blueprint_id'])
    equipment = validate_equipment_inventory(equipment_inventory,
        str(ego_bp.id), config['installed_backup_lamp_count'])
    owned = []
    try:
        for bp, route, label in ((ego_bp, ego_route, 'ego'),
                                 (other_bp, other_route, 'other vehicle')):
            transform = route['start'].transform
            actor = world.try_spawn_actor(bp, transform)
            if actor is None:
                raise ValueError(label + ' Native actor spawn failed')
            owned.append(actor)
        equipment['actor_id'] = owned[0].id
        context = {'junction_id': ego_route['junction_id'],
                   'other_vehicle_purpose': 'perpendicular moving intersection context',
                   'other_vehicle_priority': 'unresolved pending source review',
                   'ego_road_id': ego_route['road_id'],
                   'other_road_id': other_route['road_id']}
        return {'ego': owned[0], 'other': owned[1], 'owned': owned,
                'ego_route': ego_route, 'other_route': other_route,
                'equipment': equipment, 'context': context}
    except BaseException:
        for actor in reversed(owned):
            actor.destroy()
        raise


def drive_through(actor, world_map, carla, route, *, speed_mps=5., gain=.2):
    """Follow the selected source lane; reject branch or wrong-road drift."""
    transform = actor.get_transform()
    wp = world_map.get_waypoint(transform.location)
    if wp is None or int(wp.road_id) != route['road_id']:
        raise ValueError('Participant left selected approach road')
    options = [n for n in wp.next(6.)
               if _angle_difference(_yaw(n), _yaw(route['start'])) <= 25]
    if len(options) != 1:
        raise ValueError('Through lane lookahead ambiguous')
    target = options[0].transform.location
    desired = atan2(target.y-transform.location.y, target.x-transform.location.x)
    yaw = radians(transform.rotation.yaw)
    error = atan2(sin(desired-yaw), cos(desired-yaw))
    velocity = actor.get_velocity()
    speed = hypot(velocity.x, velocity.y)
    delta = speed_mps-speed
    actor.apply_control(carla.VehicleControl(
        throttle=min(.65, max(0., gain*delta)),
        brake=min(.8, max(0., -.3*delta)),
        steer=min(.45, max(-.45, error/.6))))


def set_backup_lamp(actor, carla, desired_on):
    """Set and read back the Native bit, preserving all unrelated lamp bits."""
    mask = int(carla.VehicleLightState.Reverse)
    before = int(actor.get_light_state())
    desired = before | mask if desired_on else before & ~mask
    actor.set_light_state(carla.VehicleLightState(desired))
    actual = int(actor.get_light_state())
    if actual != desired:
        raise ValueError('Native backup-lamp state readback mismatch')
    return bool(actual & mask)

import json
from pathlib import Path
import sys
from tempfile import TemporaryDirectory
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from lamp_source_capture import LampSourceRecorder
from backup_lamp_measurement import measure


class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y


class Transform:
    def get_forward_vector(self):
        return Vector(1, 0)


class Ego:
    id = 42
    state = 0

    def get_transform(self):
        return Transform()

    def get_velocity(self):
        return Vector(3, 0)

    def get_light_state(self):
        return self.state


class LampSourceCaptureTests(unittest.TestCase):
    def test_retains_native_state_and_original_motion(self):
        with TemporaryDirectory() as directory:
            ego = Ego()
            equipment = {'actor_id': 42, 'kind': 'motor_vehicle',
                         'blueprint_source_sha256': 'a' * 64,
                         'installed_backup_lamps': ['rear-left']}
            with LampSourceRecorder(directory, ego, equipment, 8) as recorder:
                first = recorder.append(100, 0)
                ego.state = 8
                second = recorder.append(101, 0.05)
                self.assertFalse(first['native_backup_lamp_bit'])
                self.assertTrue(second['native_backup_lamp_bit'])
                with self.assertRaisesRegex(ValueError, 'missing or unordered'):
                    recorder.append(103, 0.1)
            rows = [json.loads(line) for line in (Path(directory) / 'motion.jsonl').read_text().splitlines()]
            self.assertEqual([row['frame'] for row in rows], [100, 101])
            self.assertEqual(rows[1]['native_light_state_bits'], 8)
            frame_map = Path(directory) / 'video_frames.jsonl'
            frame_map.write_text(''.join(json.dumps({'video_frame': index,
                'carla_frame': row['frame'], 'time_s': row['time_s']}) + '\n'
                for index, row in enumerate(rows)))
            observed = measure(Path(directory) / 'motion.jsonl',
                               Path(directory) / 'equipment.json', frame_map)
            self.assertEqual(observed['forward_frames'], [100, 101])
            self.assertEqual(observed['forward_with_native_lamp_bit_frames'], [101])

    def test_rejects_unbound_equipment(self):
        with TemporaryDirectory() as directory:
            with self.assertRaisesRegex(ValueError, 'identity differs'):
                LampSourceRecorder(directory, Ego(), {'actor_id': 99, 'kind': 'motor_vehicle'}, 8)


if __name__ == '__main__':
    unittest.main()
